import React, { useState } from 'react';
import { StatusBadge, BatteryBar, SensorDot } from './UIKit';

export default function VehiclePanel({ vehicle, onTakeover, onRelease, onClean, onRecall, onDeploy }) {
  const [loading, setLoading] = useState(null);

  if (!vehicle) return (
    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '100%', color: '#3a4a6a', fontFamily: 'monospace', fontSize: 13 }}>
      Select a vehicle from the list
    </div>
  );

  async function handle(action, fn) {
    setLoading(action);
    await fn();
    setLoading(null);
  }

  const btn = (label, action, fn, color = '#00cfff', disabled = false) => (
    <button
      onClick={() => handle(action, fn)}
      disabled={!!loading || disabled}
      style={{
        background: disabled ? 'rgba(255,255,255,0.03)' : `${color}18`,
        border: `1px solid ${disabled ? 'rgba(255,255,255,0.06)' : color + '44'}`,
        color: disabled ? '#3a4a6a' : color,
        padding: '8px 14px', borderRadius: 8, fontSize: 11, fontFamily: 'monospace',
        cursor: disabled || loading ? 'not-allowed' : 'pointer', flex: 1, fontWeight: 600,
        letterSpacing: 0.5, transition: 'all 0.15s', textTransform: 'uppercase',
      }}
    >
      {loading === action ? '...' : label}
    </button>
  );

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 14, height: '100%', overflowY: 'auto', paddingRight: 4 }}>
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between' }}>
        <div>
          <div style={{ fontSize: 22, fontWeight: 700, color: '#e0eaff', fontFamily: 'monospace' }}>{vehicle.id}</div>
          <div style={{ marginTop: 4 }}><StatusBadge status={vehicle.status} /></div>
        </div>
        <div style={{ textAlign: 'right' }}>
          <div style={{ fontSize: 11, color: '#556677' }}>Total Trips</div>
          <div style={{ fontSize: 20, fontWeight: 700, color: '#00cfff', fontFamily: 'monospace' }}>{vehicle.totalTrips}</div>
        </div>
      </div>

      {/* Alerts */}
      {vehicle.alerts?.map((alert, i) => (
        <div key={i} style={{
          background: alert.type === 'CRITICAL' ? 'rgba(255,34,68,0.12)' : 'rgba(0,207,255,0.08)',
          border: `1px solid ${alert.type === 'CRITICAL' ? '#ff224466' : '#00cfff44'}`,
          borderRadius: 8, padding: '8px 12px', fontSize: 11, fontFamily: 'monospace',
          color: alert.type === 'CRITICAL' ? '#ff6680' : '#00cfff',
          display: 'flex', alignItems: 'center', gap: 8,
        }}>
          <span>{alert.type === 'CRITICAL' ? '⚠' : 'ℹ'}</span>{alert.msg}
        </div>
      ))}

      {/* Telemetry Grid */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8 }}>
        {[
          { label: 'Speed', value: `${Math.round(vehicle.speed)}`, unit: 'km/h', color: '#00ff88' },
          { label: 'Passengers', value: vehicle.passengers, unit: 'pax', color: '#00cfff' },
          { label: 'Heading', value: `${Math.round(vehicle.heading)}°`, unit: '', color: '#ffcc00' },
          { label: 'Cleanliness', value: `${vehicle.cleanlinessScore}`, unit: '%', color: vehicle.cleanlinessScore > 70 ? '#00ff88' : '#ff6b35' },
        ].map(m => (
          <div key={m.label} style={{ background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.06)', borderRadius: 10, padding: '10px 14px' }}>
            <div style={{ fontSize: 9, color: '#556677', textTransform: 'uppercase', letterSpacing: 1.5, marginBottom: 4 }}>{m.label}</div>
            <div style={{ fontSize: 20, fontWeight: 700, color: m.color, fontFamily: 'monospace' }}>
              {m.value}<span style={{ fontSize: 10, color: '#556677', marginLeft: 3 }}>{m.unit}</span>
            </div>
          </div>
        ))}
      </div>

      {/* Battery */}
      <div style={{ background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.06)', borderRadius: 10, padding: '10px 14px' }}>
        <div style={{ fontSize: 9, color: '#556677', textTransform: 'uppercase', letterSpacing: 1.5, marginBottom: 8 }}>Battery</div>
        <BatteryBar value={vehicle.battery} />
      </div>

      {/* Route */}
      {vehicle.route && (
        <div style={{ background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.06)', borderRadius: 10, padding: '10px 14px' }}>
          <div style={{ fontSize: 9, color: '#556677', textTransform: 'uppercase', letterSpacing: 1.5, marginBottom: 4 }}>Route</div>
          <div style={{ fontSize: 12, color: '#e0eaff', fontFamily: 'monospace' }}>{vehicle.route}</div>
          {vehicle.distanceToDestination > 0 && (
            <div style={{ fontSize: 11, color: '#8899aa', marginTop: 2 }}>
              {vehicle.distanceToDestination.toFixed(1)} km remaining
            </div>
          )}
        </div>
      )}

      {/* Sensors */}
      <div style={{ background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.06)', borderRadius: 10, padding: '10px 14px' }}>
        <div style={{ fontSize: 9, color: '#556677', textTransform: 'uppercase', letterSpacing: 1.5, marginBottom: 8 }}>Sensors</div>
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 6 }}>
          {Object.entries(vehicle.sensors || {}).map(([k, v]) => (
            <div key={k} style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
              <SensorDot status={v} />
              <span style={{ fontSize: 11, color: '#8899aa', fontFamily: 'monospace', textTransform: 'uppercase' }}>{k}</span>
              <span style={{ fontSize: 10, color: v === 'OK' ? '#00ff88' : '#ffcc00', marginLeft: 'auto' }}>{v}</span>
            </div>
          ))}
        </div>
      </div>

      {/* Controls */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: 8, marginTop: 'auto' }}>
        <div style={{ fontSize: 9, color: '#556677', textTransform: 'uppercase', letterSpacing: 1.5 }}>Controls</div>
        <div style={{ display: 'flex', gap: 8 }}>
          {vehicle.status === 'takeover_needed' || (vehicle.status === 'autonomous' && vehicle.alerts?.length === 0)
            ? btn('⚡ Takeover', 'takeover', () => onTakeover(vehicle.id), '#ff6b35', vehicle.status === 'manual_control')
            : vehicle.status === 'manual_control'
              ? btn('↩ Release Auto', 'release', () => onRelease(vehicle.id), '#00ff88')
              : btn('⚡ Takeover', 'takeover', () => onTakeover(vehicle.id), '#ff6b35')}
        </div>
        <div style={{ display: 'flex', gap: 8 }}>
          {btn('🧹 Clean', 'clean', () => onClean(vehicle.id), '#00cfff', vehicle.status === 'cleaning')}
          {vehicle.status === 'idle' || vehicle.status === 'charging'
            ? btn('🚀 Deploy', 'deploy', () => onDeploy(vehicle.id), '#00ff88', vehicle.battery < 20)
            : btn('🔋 Recall', 'recall', () => onRecall(vehicle.id), '#ffcc00', ['charging', 'cleaning', 'idle'].includes(vehicle.status))}
        </div>
      </div>

      {vehicle.operator && (
        <div style={{ fontSize: 10, color: '#556677', fontFamily: 'monospace', textAlign: 'center' }}>
          Operator: {vehicle.operator}
        </div>
      )}
    </div>
  );
}
